const float kernelCutoff = 2.0f * h;  // Kernel cutoff radius

for (size_t i = start; i < end; ++i) {
    Particle& p = particles[i];
    std::vector<Particle*> neighbors;

    // Find neighbors using particle table
    for (uint32_t j = 0; j < particleTable[i]; ++j) {
        uint32_t neighborIdx = particleTable[i * particleCount + j];
        if (neighborIdx >= particleCount) continue;

        Particle& q = particles[neighborIdx];
        float dx = p.pos.x - q.pos.x;
        float dy = p.pos.y - q.pos.y;
        float dz = p.pos.z - q.pos.z;
        float r2 = dx*dx + dy*dy + dz*dz;

        if (r2 < kernelCutoff * kernelCutoff) {
            neighbors.push_back(&q);
        }
    }

    // Calculate pressure force
    float pressure = 0.0f;
    float density = 0.0f;
    float gradW = 0.0f;
    float lapW = 0.0f;

    for (Particle* q : neighbors) {
        float dx = p.pos.x - q->pos.x;
        float dy = p.pos.y - q->pos.y;
        float dz = p.pos.z - q->pos.z;
        float r = std::sqrt(dx*dx + dy*dy + dz*dz);
        float r2 = r * r;
        float r3 = r2 * r;
        float r4 = r3 * r;

        // Poly6 kernel for density estimation
        float poly6 = 315.0f / (64.0f * std::numeric_limits<float>::pi() * h2 * h2 * h2) *
                      std::max(0.0f, 1.0f - r / h) * std::max(0.0f, 1.0f - r / h);

        density += q->mass * poly6;

        // Spiky gradient kernel for pressure force
        float spiky = 45.0f / (std::numeric_limits<float>::pi() * h2 * h2 * h2) *
                      std::max(0.0f, 1.0f - r / h) * std::max(0.0f, 1.0f - r / h);

        pressure += -q->mass * (p.density + q->density) / (2.0f * p.density * q->density) *
                    spiky * (dx * dx + dy * dy + dz * dz) / r;

        // Viscosity force (spiky gradient)
        float gradWx = -45.0f / (std::numeric_limits<float>::pi() * h2 * h2 * h2) *
                      std::max(0.0f, 1.0f - r / h) * (dx / r) * (dx / r) * (dx / r);
        float gradWy = -45.0f / (std::numeric_limits<float>::pi() * h2 * h2 * h2) *
                      std::max(0.0f, 1.0f - r / h) * (dy / r) * (dy / r) * (dy / r);
        float gradWz = -45.0f / (std::numeric_limits<float>::pi() * h2 * h2 * h2) *
                      std::max(0.0f, 1.0f - r / h) * (dz / r) * (dz / r) * (dz / r);

        // Laplacian kernel for viscosity
        float lap = 45.0f / (std::numeric_limits<float>::pi() * h2 * h2 * h2) *
                    std::max(0.0f, 1.0f - r / h) * (1.0f - r / h) / r;

        // Update forces
        p.force.x += q->mass * (pressure * dx / r + viscosity * (q->vel.x - p.vel.x) * lap);
        p.force.y += q->mass * (pressure * dy / r + viscosity * (q->vel.y - p.vel.y) * lap);
        p.force.z += q->mass * (pressure * dz / r + viscosity * (q->vel.z - p.vel.z) * lap);
    }

    // Apply pressure force (alternative formulation)
    float pressureForce = 0.0f;
    if (density > 0.0f) {
        pressureForce = -mass * (density - restDensity) * spikyGrad;
        p.force.x += pressureForce * dx;
        p.force.y += pressureForce * dy;
        p.force.z += pressureForce * dz;
    }
}
